SELECT id, customer_id, started_at, country, ROW_NUMBER() OVER w_ordered row_seq, ROW_NUMBER() OVER (PARTITION BY MONTH(started_at), customer_id ORDER BY started_at DESC, id) seq_no, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_browser, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at, id) row_seq_2 FROM sessions WINDOW w_ordered AS (PARTITION BY country ORDER BY started_at, id);
